window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dfe4820e365311bc"]={"versions": [{"id": "FIG-dfe4820e365311bc", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Bereitstellungsdiagramm (Deployment- und Kommunikationssicht) für die signal-zu-dienst-basierte Übersetzung zwischen AUTOSAR Adaptive Platform und AUTOSAR Classic Platform. Das Diagramm illustriert das architektonische Muster, bei dem eine Signal-to-Service-Translation in einem separaten Applikationsprozess auf einer <code>Adaptive Machine</code> gekapselt ist, um eine Brücke zwischen der dienstorientierten Kommunikation einer <code>Adaptive Application</code> und der signalbasierten Kommunikation einer <code>Classic SWC</code> über Netzwerk-Gateways zu schlagen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in drei physische/logische Knoten sowie Kommunikationsmedien:</p>\n<ul class=\"fig-list\">\n<li><strong>Adaptive Machine</strong>: Beherbergt zwei separate Prozesse (<code>Process</code>):</li>\n<li>Erster Prozess mit der <code>Adaptive Application</code>, ausgestattet mit einem dienstorientierten Port (<code>Service oriented communication</code>).</li>\n<li>Zweiter Prozess mit der Übersetzungskomponente <code>Signal / Service Translation</code>, die an der Oberseite über einen Dienstport und an der Unterseite über eine PDU-Schnittstelle (<code>PDU</code>, gegliedert in Signalfelder) verfügt.</li>\n<li>Zwischen den beiden Prozessen vermittelt die Zwischenschicht <code>ara::com</code> über gepunktete Verbindungslinien zwischen den Ports.</li>\n<li><strong>Gateway ECU (Classic AUTOSAR)</strong>: Klassisches Steuergerät, das als Netzwerkübergang zwischen Ethernet und CAN fungiert.</li>\n<li><strong>Classic ECU</strong>: Beherbergt eine klassische Software-Komponente (<code>Classic SWC</code>) mit signalbasiertem Port (<code>Signal based communication</code>).</li>\n<li><strong>Netzwerke und Artefakte</strong>:</li>\n<li><code>Ethernet</code> verbindet die <code>Adaptive Machine</code> mit dem <code>Gateway ECU (Classic AUTOSAR)</code>.</li>\n<li><code>CAN</code> verbindet das <code>Gateway ECU (Classic AUTOSAR)</code> mit der <code>Classic ECU</code>.</li>\n<li><code>Communication Matrix + signal-service Mapping</code>: Dateisymbol/Konfigurationsartefakt, das der Ethernet-Verbindung der <code>Adaptive Machine</code> zugeordnet ist.</li>\n<li><strong>Logische Assoziation</strong>: Eine breite, hellblaue gestrichelte Linie visualisiert den logischen End-to-End-Kommunikationspfad zwischen dem Port der <code>Adaptive Application</code> und dem Port der <code>Classic SWC</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Signal- und Nachrichtenfluss</strong>: Signale aus der <code>Classic SWC</code> werden über den CAN-Bus in PDUs übertragen.</li>\n<li>Das <code>Gateway ECU (Classic AUTOSAR)</code> leitet die CAN-Frames/PDUs über die Ethernet-Verbindung an die <code>Adaptive Machine</code> weiter.</li>\n<li>Auf der <code>Adaptive Machine</code> empfängt der Übersetzungsprozess (<code>Signal / Service Translation</code>) die PDU über das Netzwerk.</li>\n<li>Die Komponente <code>Signal / Service Translation</code> wandelt die PDU-Signale anhand der bereitgestellten <code>Communication Matrix + signal-service Mapping</code> in dienstorientierte Events, Methoden oder Felder um.</li>\n<li>Über <code>ara::com</code> wird die übersetzte Service-Instanz prozessübergreifend an die <code>Adaptive Application</code> bereitgestellt.</li>\n<li>Aus Sicht der Anwendungsentwicklung kommunizieren <code>Adaptive Application</code> und <code>Classic SWC</code> logisch transparent miteinander, abstrahiert über Dienst- bzw. Signalgrenzen hinweg.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Signal-zu-Service-Übersetzung wird als reguläre Software-Lösung auf Anwendungsebene realisiert, nicht zwingend im AUTOSAR-Basis-Stack integriert.</li>\n<li>Erfordert eine duale Bereitstellungskonfiguration: Einerseits PDU-Beschreibungen aus der klassischen Kommunikationsmatrix (System Description), andererseits Manifest-Definitionen für das Signal-Service-Mapping (<code>signal-service Mapping</code>) sowie Service-Schnittstellenbeschreibungen für <code>ara::com</code>.</li>\n<li>Die Entkopplung in zwei separate OS-Prozesse erfordert IPC-Mechanismen über <code>ara::com</code> innerhalb der Machine sowie die Handhabung von PDU-Empfang/Versand auf Socket- bzw. Ethernet-Ebene im Translationsprozess.</li>\n</ul>"}, {"id": "FIG-761262bfbdeedf7e", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Bereitstellungsdiagramm (Deployment- und Kommunikationssicht) für die signal-zu-dienst-basierte Übersetzung zwischen AUTOSAR Adaptive Platform und AUTOSAR Classic Platform. Das Diagramm illustriert das architektonische Muster, bei dem eine Signal-to-Service-Translation in einem separaten Applikationsprozess auf einer <code>Adaptive Machine</code> gekapselt ist, um eine Brücke zwischen der dienstorientierten Kommunikation einer <code>Adaptive Application</code> und der signalbasierten Kommunikation einer <code>Classic SWC</code> über Netzwerk-Gateways zu schlagen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in drei physische/logische Knoten sowie Kommunikationsmedien:</p>\n<ul class=\"fig-list\">\n<li><strong>Adaptive Machine</strong>: Beherbergt zwei separate Prozesse (<code>Process</code>):</li>\n<li>Erster Prozess mit der <code>Adaptive Application</code>, ausgestattet mit einem dienstorientierten Port (<code>Service oriented communication</code>).</li>\n<li>Zweiter Prozess mit der Übersetzungskomponente <code>Signal / Service Translation</code>, die an der Oberseite über einen Dienstport und an der Unterseite über eine PDU-Schnittstelle (<code>PDU</code>, gegliedert in Signalfelder) verfügt.</li>\n<li>Zwischen den beiden Prozessen vermittelt die Zwischenschicht <code>ara::com</code> über gepunktete Verbindungslinien zwischen den Ports.</li>\n<li><strong>Gateway ECU (Classic AUTOSAR)</strong>: Klassisches Steuergerät, das als Netzwerkübergang zwischen Ethernet und CAN fungiert.</li>\n<li><strong>Classic ECU</strong>: Beherbergt eine klassische Software-Komponente (<code>Classic SWC</code>) mit signalbasiertem Port (<code>Signal based communication</code>).</li>\n<li><strong>Netzwerke und Artefakte</strong>:</li>\n<li><code>Ethernet</code> verbindet die <code>Adaptive Machine</code> mit dem <code>Gateway ECU (Classic AUTOSAR)</code>.</li>\n<li><code>CAN</code> verbindet das <code>Gateway ECU (Classic AUTOSAR)</code> mit der <code>Classic ECU</code>.</li>\n<li><code>Communication Matrix + signal-service Mapping</code>: Dateisymbol/Konfigurationsartefakt, das der Ethernet-Verbindung der <code>Adaptive Machine</code> zugeordnet ist.</li>\n<li><strong>Logische Assoziation</strong>: Eine breite, hellblaue gestrichelte Linie visualisiert den logischen End-to-End-Kommunikationspfad zwischen dem Port der <code>Adaptive Application</code> und dem Port der <code>Classic SWC</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Signal- und Nachrichtenfluss</strong>: Signale aus der <code>Classic SWC</code> werden über den CAN-Bus in PDUs übertragen.</li>\n<li>Das <code>Gateway ECU (Classic AUTOSAR)</code> leitet die CAN-Frames/PDUs über die Ethernet-Verbindung an die <code>Adaptive Machine</code> weiter.</li>\n<li>Auf der <code>Adaptive Machine</code> empfängt der Übersetzungsprozess (<code>Signal / Service Translation</code>) die PDU über das Netzwerk.</li>\n<li>Die Komponente <code>Signal / Service Translation</code> wandelt die PDU-Signale anhand der bereitgestellten <code>Communication Matrix + signal-service Mapping</code> in dienstorientierte Events, Methoden oder Felder um.</li>\n<li>Über <code>ara::com</code> wird die übersetzte Service-Instanz prozessübergreifend an die <code>Adaptive Application</code> bereitgestellt.</li>\n<li>Aus Sicht der Anwendungsentwicklung kommunizieren <code>Adaptive Application</code> und <code>Classic SWC</code> logisch transparent miteinander, abstrahiert über Dienst- bzw. Signalgrenzen hinweg.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Signal-zu-Service-Übersetzung wird als reguläre Software-Lösung auf Anwendungsebene realisiert, nicht zwingend im AUTOSAR-Basis-Stack integriert.</li>\n<li>Erfordert eine duale Bereitstellungskonfiguration: Einerseits PDU-Beschreibungen aus der klassischen Kommunikationsmatrix (System Description), andererseits Manifest-Definitionen für das Signal-Service-Mapping (<code>signal-service Mapping</code>) sowie Service-Schnittstellenbeschreibungen für <code>ara::com</code>.</li>\n<li>Die Entkopplung in zwei separate OS-Prozesse erfordert IPC-Mechanismen über <code>ara::com</code> innerhalb der Machine sowie die Handhabung von PDU-Empfang/Versand auf Socket- bzw. Ethernet-Ebene im Translationsprozess.</li>\n</ul>"}, {"id": "FIG-a85d7ed805025cb4", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Bereitstellungsdiagramm (Deployment- und Kommunikationssicht) für die signal-zu-dienst-basierte Übersetzung zwischen AUTOSAR Adaptive Platform und AUTOSAR Classic Platform. Das Diagramm illustriert das architektonische Muster, bei dem eine Signal-to-Service-Translation in einem separaten Applikationsprozess auf einer <code>Adaptive Machine</code> gekapselt ist, um eine Brücke zwischen der dienstorientierten Kommunikation einer <code>Adaptive Application</code> und der signalbasierten Kommunikation einer <code>Classic SWC</code> über Netzwerk-Gateways zu schlagen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in drei physische/logische Knoten sowie Kommunikationsmedien:</p>\n<ul class=\"fig-list\">\n<li><strong>Adaptive Machine</strong>: Beherbergt zwei separate Prozesse (<code>Process</code>):</li>\n<li>Erster Prozess mit der <code>Adaptive Application</code>, ausgestattet mit einem dienstorientierten Port (<code>Service oriented communication</code>).</li>\n<li>Zweiter Prozess mit der Übersetzungskomponente <code>Signal / Service Translation</code>, die an der Oberseite über einen Dienstport und an der Unterseite über eine PDU-Schnittstelle (<code>PDU</code>, gegliedert in Signalfelder) verfügt.</li>\n<li>Zwischen den beiden Prozessen vermittelt die Zwischenschicht <code>ara::com</code> über gepunktete Verbindungslinien zwischen den Ports.</li>\n<li><strong>Gateway ECU (Classic AUTOSAR)</strong>: Klassisches Steuergerät, das als Netzwerkübergang zwischen Ethernet und CAN fungiert.</li>\n<li><strong>Classic ECU</strong>: Beherbergt eine klassische Software-Komponente (<code>Classic SWC</code>) mit signalbasiertem Port (<code>Signal based communication</code>).</li>\n<li><strong>Netzwerke und Artefakte</strong>:</li>\n<li><code>Ethernet</code> verbindet die <code>Adaptive Machine</code> mit dem <code>Gateway ECU (Classic AUTOSAR)</code>.</li>\n<li><code>CAN</code> verbindet das <code>Gateway ECU (Classic AUTOSAR)</code> mit der <code>Classic ECU</code>.</li>\n<li><code>Communication Matrix + signal-service Mapping</code>: Dateisymbol/Konfigurationsartefakt, das der Ethernet-Verbindung der <code>Adaptive Machine</code> zugeordnet ist.</li>\n<li><strong>Logische Assoziation</strong>: Eine breite, hellblaue gestrichelte Linie visualisiert den logischen End-to-End-Kommunikationspfad zwischen dem Port der <code>Adaptive Application</code> und dem Port der <code>Classic SWC</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Signal- und Nachrichtenfluss</strong>: Signale aus der <code>Classic SWC</code> werden über den CAN-Bus in PDUs übertragen.</li>\n<li>Das <code>Gateway ECU (Classic AUTOSAR)</code> leitet die CAN-Frames/PDUs über die Ethernet-Verbindung an die <code>Adaptive Machine</code> weiter.</li>\n<li>Auf der <code>Adaptive Machine</code> empfängt der Übersetzungsprozess (<code>Signal / Service Translation</code>) die PDU über das Netzwerk.</li>\n<li>Die Komponente <code>Signal / Service Translation</code> wandelt die PDU-Signale anhand der bereitgestellten <code>Communication Matrix + signal-service Mapping</code> in dienstorientierte Events, Methoden oder Felder um.</li>\n<li>Über <code>ara::com</code> wird die übersetzte Service-Instanz prozessübergreifend an die <code>Adaptive Application</code> bereitgestellt.</li>\n<li>Aus Sicht der Anwendungsentwicklung kommunizieren <code>Adaptive Application</code> und <code>Classic SWC</code> logisch transparent miteinander, abstrahiert über Dienst- bzw. Signalgrenzen hinweg.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Signal-zu-Service-Übersetzung wird als reguläre Software-Lösung auf Anwendungsebene realisiert, nicht zwingend im AUTOSAR-Basis-Stack integriert.</li>\n<li>Erfordert eine duale Bereitstellungskonfiguration: Einerseits PDU-Beschreibungen aus der klassischen Kommunikationsmatrix (System Description), andererseits Manifest-Definitionen für das Signal-Service-Mapping (<code>signal-service Mapping</code>) sowie Service-Schnittstellenbeschreibungen für <code>ara::com</code>.</li>\n<li>Die Entkopplung in zwei separate OS-Prozesse erfordert IPC-Mechanismen über <code>ara::com</code> innerhalb der Machine sowie die Handhabung von PDU-Empfang/Versand auf Socket- bzw. Ethernet-Ebene im Translationsprozess.</li>\n</ul>"}, {"id": "FIG-ad0e8102e86d75ba", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Bereitstellungsdiagramm (Deployment- und Kommunikationssicht) für die Signal-zu-Service-Übersetzung zwischen AUTOSAR Adaptive Platform und AUTOSAR Classic Platform. Das Diagramm beschreibt das architektonische Entwurfsmuster, bei dem die <code>Signal / Service Translation</code> und die <code>Adaptive Application</code> innerhalb desselben Betriebssystemprozesses auf einer <code>Adaptive Machine</code> instanziiert sind und das Plattform-Funktionscluster <code>Communication Management</code> für den hardwarenahen Ethernet-Transport der PDUs nutzt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Steuergeräte-/Maschinen-Knoten, Bussysteme und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><strong>Adaptive Machine</strong>:</li>\n<li>Enthält einen gemeinsamen Betriebssystemprozess (<code>Process</code>), in dem sowohl die <code>Adaptive Application</code> als auch die <code>Signal / Service Translation</code> laufen.</li>\n<li>Die <code>Adaptive Application</code> besitzt einen Dienst-Port (<code>Service oriented communication</code>).</li>\n<li>Die <code>Signal / Service Translation</code> bindet direkt an diesen Port an (<code>translated service instance</code>) und enthält intern das Konfigurationsartefakt <code>Communication Matrix + signal-service Mapping</code> sowie die PDU-Pufferschnittstelle (<code>PDU</code>).</li>\n<li>Auf Maschinenebene unterhalb des Prozesses liegt der funktionale Plattformblock <code>Communication Management</code>.</li>\n<li><strong>Gateway ECU (Classic AUTOSAR)</strong>:</li>\n<li>Verbindet Ethernet und CAN.</li>\n<li>Enthält eine interne PDU-Weiterleitung, dargestellt durch eine PDU auf der CAN-Schnittstelle, einen internen gestrichelten Richtungspfeil und eine PDU auf der Ethernet-Schnittstelle.</li>\n<li><strong>Classic ECU</strong>: Beherbergt die <code>Classic SWC</code> mit signalbasiertem Port (<code>Signal based communication</code>).</li>\n<li><strong>Netzwerke und logische Verbindungen</strong>:</li>\n<li><code>Ethernet</code> verbindet <code>Adaptive Machine</code> (über PDU-Darstellung) mit <code>Gateway ECU</code>.</li>\n<li><code>CAN</code> verbindet <code>Gateway ECU</code> mit <code>Classic ECU</code>.</li>\n<li>Eine breite, hellblaue gestrichelte Linie kennzeichnet die logische Ende-zu-Ende-Beziehung zwischen <code>Adaptive Application</code> und <code>Classic SWC</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Die <code>Classic SWC</code> sendet Signale über den CAN-Bus an das <code>Gateway ECU (Classic AUTOSAR)</code>.</li>\n<li>Im <code>Gateway ECU</code> werden die CAN-PDUs netzwerkübergreifend direkt in Ethernet-PDUs umgesetzt bzw. weitergeleitet (illustriert durch die PDU-Kette und den grünen Richtungspfeil im Gateway).</li>\n<li>Die Ethernet-PDUs erreichen die <code>Adaptive Machine</code> und werden über das Funktionscluster <code>Communication Management</code> an den Prozess weitergegeben.</li>\n<li>Die komponenteninterne <code>Signal / Service Translation</code> verarbeitet die PDU gemäß dem eingebetteten <code>Communication Matrix + signal-service Mapping</code> und stellt sie der <code>Adaptive Application</code> prozessintern als <code>translated service instance</code> bereit.</li>\n<li>Der logische Kommunikationspfad überbrückt somit transparent die Lücke zwischen Dienst- und Signalwelt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Zusammenlegung von <code>Adaptive Application</code> und <code>Signal / Service Translation</code> in denselben Betriebssystemprozess eliminiert die Notwendigkeit für prozessübergreifendes IPC via <code>ara::com</code> für die Übersetzungsebene; die Übersetzung agiert als Adapter/Bibliothek oder Sub-Komponente innerhalb des Anwendungs-Deployments.</li>\n<li>Das Konfigurationsartefakt <code>Communication Matrix + signal-service Mapping</code> wird direkt als Teil des Anwendungsprozess-Deployments instantiiert.</li>\n<li>Das Cluster <code>Communication Management</code> übernimmt die PDU-basierte Netzwerkabstraktion auf der Adaptive Machine.</li>\n<li>Die Gateway-Funktionalität der Classic ECU ist als deterministisches PDU-Routing spezifiziert.</li>\n</ul>"}], "trans": [{"from": "FIG-dfe4820e365311bc", "to": "FIG-761262bfbdeedf7e", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-761262bfbdeedf7e", "to": "FIG-a85d7ed805025cb4", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a85d7ed805025cb4", "to": "FIG-ad0e8102e86d75ba", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Adaptive Machine / Prozessarchitektur</strong>: <code>Adaptive Application</code> und <code>Signal / Service Translation</code> laufen nun innerhalb desselben gemeinsamen Betriebssystemprozesses (<code>Process</code>), statt in zwei getrennten Prozessen.</li>\n<li><strong>Dienstverbindung / Middleware</strong>: Der separate Vermittlungsblock <code>ara::com</code> entfällt; die Interaktion zwischen Applikationsport und Translation erfolgt als direkte Kopplung via <code>translated service instance</code>.</li>\n<li><strong>Plattform-Schicht</strong>: Ergänzung des Funktionsclusters <code>Communication Management</code> als eigenständiger oranger Block auf Knotenebene der <code>Adaptive Machine</code>.</li>\n<li><strong>Artefakt-Zuordnung</strong>: Das Konfigurationsartefakt <code>Communication Matrix + signal-service Mapping</code> ist direkt in den Prozess bzw. an die <code>Signal / Service Translation</code> eingebettet, statt extern am Ethernet-Netzwerkzweig zu liegen.</li>\n<li><strong>Gateway-Datenfluss</strong>: Explizite Modellierung der Weiterleitung von PDUs im <code>Gateway ECU (Classic AUTOSAR)</code> durch PDU-Darstellungen auf CAN- und Ethernet-Ebene samt gerichtetem gestricheltem Übergangspfeil von CAN nach Ethernet.</li>\n</ul>"}]};
